#!/usr/bin/env python3
"""
Generate per-session reports and dashboard from master index.
"""

import json, os, re
from datetime import datetime
from collections import Counter

OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
INDEX_PATH = os.path.join(OUTPUT_DIR, 'MASTER_INDEX.json')

with open(INDEX_PATH, 'r', encoding='utf-8') as f:
    all_sessions = json.load(f)

# ============================================================
# GENERATE PER-SESSION REPORTS (for significant sessions)
# ============================================================
significant_sessions = [s for s in all_sessions if s['status'] in ('Completed', 'Partial', 'Ongoing')]
print(f"Generating reports for {len(significant_sessions)} significant sessions...")

for session in significant_sessions[:200]:  # Top 200
    tool = session['tool']
    sid = session['id']
    title = session['title']
    safe_sid = re.sub(r'[^a-zA-Z0-9_-]', '_', sid)
    report_path = os.path.join(OUTPUT_DIR, f'{tool}-{safe_sid}.md')

    report = f"""# Session Report: {title}

## Metadata
- **ID**: {sid}
- **Tool**: {tool}
- **Date**: {session.get('date', 'Unknown')}
- **Status**: {session.get('status', 'Unknown')}
- **Turns**: {session.get('turns_user', 0)} user / {session.get('turns_assistant', 0)} assistant

## Summary
{session.get('summary', 'No summary available.')}

## Full Prompt / Objective
{session.get('full_prompt', 'N/A')}

## Status Assessment
{session.get('status', 'Unknown')} - {session.get('recommendations', 'No recommendations.')}

## Recommendations
- {session.get('recommendations', 'Review session artifacts and document outcomes.')}

## Tags
{tool}, {session.get('status', 'unknown')}
"""

    with open(report_path, 'w', encoding='utf-8') as f:
        f.write(report)

print(f"Generated {min(len(significant_sessions), 200)} session reports")

# ============================================================
# GENERATE MASTER INDEX MARKDOWN
# ============================================================
print("Generating MASTER_INDEX.md...")

by_tool = Counter(s['tool'] for s in all_sessions)
by_status = Counter(s['status'] for s in all_sessions)
by_date = Counter(s['date'] for s in all_sessions if s['date'] != 'Unknown')

total_turns_user = sum(s.get('turns_user', 0) for s in all_sessions)
total_turns_assistant = sum(s.get('turns_assistant', 0) for s in all_sessions)

md = f"""# Master Session Index

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Total Sessions**: {len(all_sessions)}
**Total Turns**: {total_turns_user} user / {total_turns_assistant} assistant

## Statistics

### By Tool
| Tool | Sessions | % |
|------|----------|---|
"""
for tool, count in sorted(by_tool.items(), key=lambda x: -x[1]):
    pct = count / len(all_sessions) * 100
    md += f"| {tool} | {count} | {pct:.1f}% |\n"

md += f"""
### By Status
| Status | Count | % |
|--------|-------|---|
"""
for status, count in sorted(by_status.items(), key=lambda x: -x[1]):
    pct = count / len(all_sessions) * 100
    md += f"| {status} | {count} | {pct:.1f}% |\n"

md += f"""
### Date Range
- **Start**: {min(by_date.keys()) if by_date else 'N/A'}
- **End**: {max(by_date.keys()) if by_date else 'N/A'}
- **Most Active**: {sorted(by_date.items(), key=lambda x: -x[1])[0][0] if by_date else 'N/A'} ({sorted(by_date.items(), key=lambda x: -x[1])[0][1] if by_date else 0} sessions)

## Sessions by Tool

"""
for tool in sorted(by_tool.keys()):
    sessions = [s for s in all_sessions if s['tool'] == tool]
    md += f"### {tool} ({len(sessions)} sessions)\n\n"
    md += "| ID | Date | Title | Status | Turns |\n"
    md += "|-----|------|-------|--------|-------|\n"
    for s in sessions[:50]:
        md += f"| {s['id'][:12]} | {s.get('date','?')[:10]} | {s['title'][:60]} | {s.get('status','?')} | {s.get('turns_user',0)}u/{s.get('turns_assistant',0)}a |\n"
    if len(sessions) > 50:
        md += f"\n... and {len(sessions)-50} more sessions\n"
    md += "\n"

with open(os.path.join(OUTPUT_DIR, 'MASTER_INDEX.md'), 'w', encoding='utf-8') as f:
    f.write(md)
print("Generated MASTER_INDEX.md")

# ============================================================
# GENERATE INTERACTIVE DASHBOARD
# ============================================================
print("Generating DASHBOARD.html...")

# Prepare data for JS
sessions_js = json.dumps(all_sessions, ensure_ascii=False)

dashboard_html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Session Dashboard</title>
<style>
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', system-ui, sans-serif;
  background: #0f0f1a;
  color: #e0e0e0;
  min-height: 100vh;
}}
