  padding: 0 24px 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}}
.controls input, .controls select {{
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  color: #e0e0e0;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 14px;
