+</style>
+</head>
+<body>
+<div class="header">
+  <h1>AI Session Dashboard - 2026</h1>
+  <p>Comprehensive audit across all AI coding tools with backfilled content, project tags, and source links</p>
+</div>
+
+<div class="stats-grid">
+  <div class="stat-card">
+    <div class="stat-value">''' + str(len(sessions)) + '''</div>
+    <div class="stat-label">Total Sessions</div>
+  </div>
+  <div class="stat-card">
+    <div class="stat-value">''' + str(len(tool_counts)) + '''</div>
+    <div class="stat-label">Tools</div>
+  </div>
+  <div class="stat-card">
+    <div class="stat-value">''' + str(status_counts.get('Completed', 0)) + '''</div>
+    <div class="stat-label">Completed</div>
+  </div>
+  <div class="stat-card">
+    <div class="stat-value">''' + str(status_counts.get('Partial', 0)) + '''</div>
+    <div class="stat-label">Partial</div>
+  </div>
+  <div class="stat-card">
+    <div class="stat-value">''' + str(status_counts.get('Abandoned', 0)) + '''</div>
+    <div class="stat-label">Abandoned</div>
+  </div>
+  <div class="stat-card">
+    <div class="stat-value">''' + str(sum(1 for s in sessions if s.get('has_full_content'))) + '''</div>
+    <div class="stat-label">With Full Content</div>
+  </div>
+</div>
+
+<div class="section">
+  <h2>Per-Tool Breakdown</h2>
+  <div class="tool-grid">
+'''
+
+# Tool cards
+for tool in sorted(tool_stats.keys(), key=lambda x: -tool_stats[x]['total']):
+    stats = tool_stats[tool]
+    pct = stats['completed'] / stats['total'] * 100 if stats['total'] > 0 else 0
+    dashboard += f'''    <div class="tool-card">
+      <h3>{tool}</h3>
+      <div class="num">{stats['total']}</div>
+      <div class="sub">{stats['completed']} completed ({pct:.1f}%) | {stats['turns']:,} total turns</div>
+      <div class="bar-container">
+        <div class="bar-fill" style="width: {pct:.1f}%"></div>
+      </div>
+    </div>
+'''
+
+dashboard += '''  </div>
+</div>
+
+<div class="section">
+  <h2>Top Active Days (7-day trend)</h2>
+  <div class="trend-chart">
+'''
+
+for date, count in top_dates:
+    height_pct = (count / max_count) * 100
+    dashboard += f'''    <div class="trend-bar" style="height: {height_pct:.0f}%;">
+      <div class="tooltip">{date}: {count} sessions</div>
+    </div>
+'''
+
+dashboard += '''  </div>
+  <div class="trend-labels">
+'''
+for date, _ in top_dates:
+    dashboard += f'    <span>{date[5:]}</span>\n'
+dashboard += '''  </div>
+</div>
+
+<div class="section">
+  <h2>Project Tags</h2>
+  <div class="tag-cloud">
+'''
+for tag, count in sorted(tag_counts.items(), key=lambda x: -x[1])[:15]:
+    dashboard += f'    <div class="tag-chip" data-tag="{tag}">{tag} <span class="count">{count}</span></div>\n'
+
+dashboard += '''  </div>
+</div>
+
+<div class="controls">
+  <input type="text" id="searchInput" placeholder="Search sessions, prompts, summaries...">
+  <select id="toolFilter">
+    <option value="all">All Tools</option>
+  </select>
+  <select id="statusFilter">
+    <option value="all">All Status</option>
+    <option value="Completed">Completed</option>
+    <option value="Partial">Partial</option>
+    <option value="Abandoned">Abandoned</option>
+  </select>
+  <select id="tagFilter">
+    <option value="all">All Projects</option>
+  </select>
+  <button class="filter-btn" id="highValueBtn" onclick="toggleHighValue()">High-Value Only</button>
+  <button class="filter-btn" id="withContentBtn" onclick="toggleWithContent()">With Full Content</button>
+  <button class="filter-btn" onclick="exportCSV()">Export CSV</button>
+</div>
+
+<div class="table-container">
+  <table id="sessionTable">
+    <thead>
+      <tr>
+        <th onclick="sortBy('date')">Date</th>
+        <th onclick="sortBy('tool_norm')">Tool</th>
+        <th onclick="sortBy('title')">Title</th>
+        <th>Tags</th>
+        <th onclick="sortBy('status')">Status</th>
+        <th onclick="sortBy('turns')">Turns</th>
+        <th>Actions</th>
+      </tr>
+    </thead>
+    <tbody id="sessionTableBody">
+    </tbody>
+  </table>
+</div>
+
+<script>
+const sessions = ''' + sessions_json + ''';
+let currentSort = { field: 'date', asc: false };
+let filteredSessions = [...sessions];
+let highValueOnly = false;
+let withContentOnly = false;
+let activeTag = 'all';
+
+function init() {
+  // Populate tool filter
+  const tools = [...new Set(sessions.map(s => s.tool_norm))].sort();
+  const toolFilter = document.getElementById('toolFilter');
+  tools.forEach(tool => {
+    const opt = document.createElement('option');
+    opt.value = tool;
+    opt.textContent = tool;
+    toolFilter.appendChild(opt);
+  });
+
+  // Populate tag filter from tag chips
+  const tags = [...new Set(sessions.flatMap(s => s.tags || []))].sort();
+  const tagFilter = document.getElementById('tagFilter');
+  tags.forEach(tag => {
+    const opt = document.createElement('option');
+    opt.value = tag;
+    opt.textContent = tag;
+    tagFilter.appendChild(opt);
+  });
+
+  // Tag chip click handlers
+  document.querySelectorAll('.tag-chip').forEach(chip => {
+    chip.addEventListener('click', () => {
+      activeTag = chip.dataset.tag;
+      document.getElementById('tagFilter').value = activeTag;
+      renderTable();
+    });
+  });
+
+  renderTable();
+}
+
+function toggleHighValue() {
+  highValueOnly = !highValueOnly;
+  document.getElementById('highValueBtn').classList.toggle('active', highValueOnly);
+  renderTable();
+}
+
+function toggleWithContent() {
+  withContentOnly = !withContentOnly;
+  document.getElementById('withContentBtn').classList.toggle('active', withContentOnly);
+  renderTable();
+}
+
+function renderTable() {
+  const tbody = document.getElementById('sessionTableBody');
+  const search = document.getElementById('searchInput').value.toLowerCase();
+  const toolFilter = document.getElementById('toolFilter').value;
+  const statusFilter = document.getElementById('statusFilter').value;
+  const tagFilter = document.getElementById('tagFilter').value;
+
+  filteredSessions = sessions.filter(s => {
+    const matchSearch = !search || 
+      s.title.toLowerCase().includes(search) ||
+      s.id.toLowerCase().includes(search) ||
+      (s.full_prompt && s.full_prompt.toLowerCase().includes(search)) ||
+      (s.summary && s.summary.toLowerCase().includes(search));
+    const matchTool = toolFilter === 'all' || s.tool_norm === toolFilter;
+    const matchStatus = statusFilter === 'all' || s.status === statusFilter;
+    const matchTag = tagFilter === 'all' || (s.tags && s.tags.includes(tagFilter));
+    const matchHighValue = !highValueOnly || (s.status === 'Completed' && (s.turns_user + s.turns_assistant) >= 20);
+    const matchWithContent = !withContentOnly || s.has_full_content;
+    return matchSearch && matchTool && matchStatus && matchTag && matchHighValue && matchWithContent;
+  });
+
+  filteredSessions.sort((a, b) => {
+    let aVal = a[currentSort.field] || '';
+    let bVal = b[currentSort.field] || '';
+    if (currentSort.field === 'turns') {
+      aVal = (a.turns_user||0) + (a.turns_assistant||0);
+      bVal = (b.turns_user||0) + (b.turns_assistant||0);
+    }
+    if (typeof aVal === 'string') aVal = aVal.toLowerCase();
+    if (typeof bVal === 'string') bVal = bVal.toLowerCase();
+    if (aVal < bVal) return currentSort.asc ? -1 : 1;
+    if (aVal > bVal) return currentSort.asc ? 1 : -1;
+    return 0;
+  });
+
+  tbody.innerHTML = filteredSessions.map((s, i) => {
+    const statusClass = 'status-' + s.status.toLowerCase();
+    const dateStr = s.date ? s.date.substring(0, 10) : 'Unknown';
+    const reportUrl = s.report_url;
+    const tagsHtml = (s.tags || []).slice(0, 3).map(t => '<span class="tag-mini">' + t + '</span>').join('');
+    const contentBadge = s.has_full_content ? '<span class="content-badge">FULL</span>' : '';
+    return `
+      <tr>
+        <td>${dateStr}</td>
+        <td><span class="tool-tag">${s.tool_norm}</span></td>
+        <td>
+          <a class="title-link" href="${reportUrl}" target="_blank" rel="noopener" title="${escapeHtml(s.title)}">
+            ${escapeHtml(s.title.substring(0, 60))}${s.title.length > 60 ? '...' : ''}
+          </a>${contentBadge}
+        </td>
+        <td>${tagsHtml}</td>
+        <td><span class="status-badge ${statusClass}">${s.status}</span></td>
+        <td>${s.turns_user||0}u/${s.turns_assistant||0}a</td>
+        <td>
+          <button class="expand-btn" onclick="toggleDetail(${i})">Expand</button>
+        </td>
+      </tr>
+      <tr class="detail-row" id="detail-${i}">
+        <td colspan="7" class="detail-cell">
+          <div class="detail-section">
+            <h4>Full Prompt</h4>
+            <p>${escapeHtml(s.full_prompt || 'N/A')}</p>
+          </div>
+          <div class="detail-section">
+            <h4>Summary</h4>
+            <p>${escapeHtml(s.summary || 'No summary')}</p>
+          </div>
+          <div class="detail-section">
+            <h4>Tags</h4>
+            <p>${(s.tags || []).join(', ')}</p>
+          </div>
+          ${s.models && s.models.length ? `
+          <div class="detail-section">
+            <h4>Models Used</h4>
+            <p>${s.models.join(', ')}</p>
+          </div>` : ''}
+          <a class="report-link primary" href="${reportUrl}" target="_blank" rel="noopener">Open Full Report</a>
+          <a class="report-link" href="${s.folder}" target="_blank" rel="noopener">Open Source</a>
+        </td>
+      </tr>
+    `;
+  }).join('');
+}
+
+function toggleDetail(index) {
+  const row = document.getElementById('detail-' + index);
+  row.classList.toggle('show');
+}
+
+function escapeHtml(text) {
+  if (!text) return '';
+  const div = document.createElement('div');
+  div.textContent = text;
+  return div.innerHTML;
+}
+
+function sortBy(field) {
+  if (currentSort.field === field) {
+    currentSort.asc = !currentSort.asc;
+  } else {
+    currentSort.field = field;
+    currentSort.asc = true;
+  }
+  renderTable();
+}
+
+function exportCSV() {
+  let csv = 'ID,Tool,Date,Title,Status,Turns User,Turns Assistant,Tags,Has Full Content\\n';
+  filteredSessions.forEach(s => {
+    csv += `"${s.id}","${s.tool_norm}","${s.date}","${s.title.replace(/"/g, '""')}","${s.status}",${s.turns_user||0},${s.turns_assistant||0},"${(s.tags||[]).join('|')}",${s.has_full_content}\\n`;
+  });
+  const blob = new Blob([csv], { type: 'text/csv' });
+  const url = URL.createObjectURL(blob);
+  const a = document.createElement('a');
+  a.href = url;
+  a.download = 'session_export.csv';
+  a.click();
+}
+
+document.getElementById('searchInput').addEventListener('input', renderTable);
+document.getElementById('toolFilter').addEventListener('change', renderTable);
+document.getElementById('statusFilter').addEventListener('change', renderTable);
+document.getElementById('tagFilter').addEventListener('change', function() {
+  activeTag = this.value;
+  renderTable();
+});
+
+init();
+</script>
+</body>
+</html>'''
+
+with open(DASHBOARD_PATH, 'w', encoding='utf-8') as f:
+    f.write(dashboard)
+print(f"Dashboard written: {DASHBOARD_PATH} ({len(dashboard)} chars)")

